 if(b.guest_device!=o->queue.device || b.backend_device!=o->queue.backend || b.device_generation!=o->queue.device_generation)return SATCHEL_GRR_BAD_OBJECT;
 if(o->guard && !o->guard(o->context,cpu,b.storage_cpu,b.layout.storage_size))return SATCHEL_GRR_BAD_OBJECT;
