 uint32_t s=inputs(o,cpu);if(s)return s;SatchelGuestRasterCommand c=o->current;c.operation=SATCHEL_VULKAN_RASTER_OP_DRAW;c.draw.operation=SATCHEL_VULKAN_RASTER_OP_DRAW;c.draw.vertex_count=(uint32_t)r->x[3];c.draw.first_vertex=0;Program *p=&o->program[o->selected];c.program=p->object;c.program_generation=p->info.program_generation;c.capture_generation=p->info.capture_generation;for(unsigned i=0;i<8;i++)if(!p->info.vertex.admission.reflection.input_components[i])c.pipeline.attribute_offsets[i]=UINT32_MAX;
 c.pipeline.version=1;c.pipeline.size=sizeof(c.pipeline);c.pipeline.state=(SatchelRasterState){.known=247,.single_vertex_program=1,.viewport_transform_enabled=o->queue.viewport_transform_enabled,.depth_zero_to_one=o->queue.depth_zero_to_one,.y_negate=o->queue.y_negate,.origin_upper_left=o->queue.origin_upper_left,.alpha_test_always=((o->color>>12)&15)==8,.alpha_to_coverage=o->multisample[2],.transform_feedback=o->queue.transform_feedback};c.pipeline.format=1;c.pipeline.samples=1;c.pipeline.topology=3;c.pipeline.color_mask=15;c.pipeline.front_face=((o->polygon>>2)&1)?0:1;c.pipeline.sample_mask=1;
