 case SATCHEL_GRR_SCISSOR:for(unsigned i=1;i<5;i++)if((int32_t)r->x[i]<0)return SATCHEL_GRR_UNSUPPORTED;if(!(uint32_t)r->x[3]||!(uint32_t)r->x[4])return SATCHEL_GRR_UNSUPPORTED;o->current.draw.scissor_x=(uint32_t)r->x[1];o->current.draw.scissor_y=(uint32_t)r->x[2];o->current.draw.scissor_width=(uint32_t)r->x[3];o->current.draw.scissor_height=(uint32_t)r->x[4];o->known|=K_SCISSOR;return SATCHEL_GRR_OK;
 case SATCHEL_GRR_DEPTH_RANGE:{float n=floating(r->f[0]),f=floating(r->f[1]);if(n!=0 || f!=1)return SATCHEL_GRR_UNSUPPORTED;o->current.draw.min_depth=n;o->current.draw.max_depth=f;o->known|=K_DEPTH;return SATCHEL_GRR_OK;}
