 case SATCHEL_GRR_DEPTH_CLAMP:if((uint8_t)r->x[1])return SATCHEL_GRR_UNSUPPORTED;o->known|=K_CLAMP;return SATCHEL_GRR_OK;
 case SATCHEL_GRR_RASTER_DISCARD:if((uint8_t)r->x[1])return SATCHEL_GRR_UNSUPPORTED;o->known|=K_DISCARD;return SATCHEL_GRR_OK;
