uint32_t satchel_guest_raster_record_apply(SatchelGuestRasterRecord *o,SatchelCPUProbe *cpu,const SatchelGuestRasterStateRequest *request,SatchelGuestRasterRecordCommit commit,void *ctx){if(!o||!cpu||!request)return SATCHEL_GRR_INVALID;if(atomic_flag_test_and_set(&o->active))return SATCHEL_GRR_BUSY;if(o->retiring)return leave(o,SATCHEL_GRR_INVALID);SatchelGuestRasterStateRequest copied=*request;uint32_t s=apply(o,cpu,&copied,commit,ctx);return leave(o,s);}
uint32_t satchel_guest_raster_record_snapshot(SatchelGuestRasterRecord *o,SatchelCPUProbe *cpu,SatchelGuestRasterRequest *out){if(!o||!cpu||!out)return SATCHEL_GRR_INVALID;if(atomic_flag_test_and_set(&o->active))return SATCHEL_GRR_BUSY;if(o->retiring || !o->recorded.command_count)return leave(o,SATCHEL_GRR_INVALID);uint32_t s=target_current(o,cpu);if(!s)*out=o->recorded;return leave(o,s);}
uint32_t satchel_guest_raster_record_count(SatchelGuestRasterRecord *o){return o?o->recorded.command_count:0;}
uint32_t satchel_guest_raster_record_destroy(SatchelGuestRasterRecord **pointer){if(!pointer)return SATCHEL_GRR_INVALID;if(!*pointer)return SATCHEL_GRR_OK;SatchelGuestRasterRecord *o=*pointer;if(atomic_flag_test_and_set(&o->active))return SATCHEL_GRR_BUSY;o->retiring=1;for(unsigned i=0;i<o->program_count;i++)if(o->program[i].reference){uint32_t s=program(satchel_guest_raster_programs_release(o->programs,o->program[i].reference));if(s)return leave(o,s);o->program[i].reference=0;}for(unsigned i=0;i<o->lease_count;i++)if(o->leases[i].lease){uint32_t s=pool(satchel_guest_pools_release(o->pools,o->leases[i].lease));if(s)return leave(o,s);o->leases[i].lease=0;}if(o->texture_ref){uint32_t s=texture(satchel_guest_textures_release(o->textures,o->texture_ref));if(s)return leave(o,s);o->texture_ref=0;}free(o);*pointer=NULL;return SATCHEL_GRR_OK;}
